CREATE FUNCTION pg_temp.version_trade_offer() RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE f record; offered uuid; requested uuid;
BEGIN
  SELECT * INTO f FROM version_fixture;
  SELECT player_id INTO offered FROM public.roster_players WHERE member_id=f.member_ids[1] AND NOT is_on_ir AND NOT is_on_taxi ORDER BY player_id LIMIT 1;
  SELECT player_id INTO requested FROM public.roster_players WHERE member_id=f.member_ids[2] AND NOT is_on_ir AND NOT is_on_taxi ORDER BY player_id LIMIT 1;
  RETURN public.propose_trade_atomic(f.league_id,f.season_id,f.member_ids[1],f.member_ids[2],ARRAY[offered],ARRAY[requested],'{}','{}');
END;
$$;
CALL pg_temp.version_write('remove trade block',$cmd$SELECT public.remove_trade_block_item_atomic((SELECT id FROM public.trade_block_items WHERE league_id=f.league_id LIMIT 1),f.member_ids[1],f.user_ids[1]) FROM version_fixture f$cmd$);
SET request.jwt.claim.sub='';
CALL pg_temp.version_write('offer with plan',$cmd$UPDATE version_fixture SET trade_id=pg_temp.version_trade_offer()$cmd$);
CALL pg_temp.version_write('trade roster plan',$cmd$SELECT public.set_trade_roster_plan_atomic(f.trade_id,f.member_ids[2],f.user_ids[2],'{}',ARRAY[(SELECT player_id FROM public.trade_items WHERE trade_id=f.trade_id AND to_member_id=f.member_ids[2] AND player_id IS NOT NULL LIMIT 1)],'{}') FROM version_fixture f$cmd$);
CALL pg_temp.version_write('unchanged taxi destinations',$cmd$SELECT public.set_trade_taxi_destinations_atomic(trade_id,member_ids[2],'{}',user_ids[2]) FROM version_fixture$cmd$,0);
CALL pg_temp.version_write('accept trade with plan',$cmd$SELECT public.accept_trade_with_plan_atomic(trade_id,member_ids[2],user_ids[2],'{}','{}','{}') FROM version_fixture$cmd$);
CALL pg_temp.version_write('end trade veto window',$cmd$UPDATE public.trades SET veto_window_expires_at=now()-interval '1 minute' WHERE id=(SELECT trade_id FROM version_fixture)$cmd$);
CALL pg_temp.version_write('complete accepted trade',$cmd$SELECT public.complete_accepted_trade_atomic(trade_id) FROM version_fixture$cmd$);
CALL pg_temp.version_write('offer for rejection',$cmd$UPDATE version_fixture SET trade_id=pg_temp.version_trade_offer()$cmd$);
CALL pg_temp.version_write('reject trade',$cmd$SELECT public.reject_trade_atomic(trade_id,member_ids[2],user_ids[2]) FROM version_fixture$cmd$);
CALL pg_temp.version_write('offer for queue',$cmd$UPDATE version_fixture SET trade_id=pg_temp.version_trade_offer()$cmd$);
CALL pg_temp.version_write('accept trade',$cmd$SELECT public.accept_trade_atomic(trade_id,member_ids[2]) FROM version_fixture$cmd$);
CALL pg_temp.version_write('ready queued trade',$cmd$UPDATE public.trades SET veto_window_expires_at=now()-interval '1 minute' WHERE id=(SELECT trade_id FROM version_fixture)$cmd$);
CALL pg_temp.version_write('due trade worker',$cmd$SELECT public.process_due_accepted_trades_atomic(1)$cmd$);
CALL pg_temp.version_write('offer for expiry',$cmd$UPDATE version_fixture SET trade_id=pg_temp.version_trade_offer()$cmd$);
CALL pg_temp.version_write('ready pending expiry',$cmd$UPDATE public.trades SET expires_at=now()-interval '1 minute' WHERE id=(SELECT trade_id FROM version_fixture)$cmd$);
CALL pg_temp.version_write('pending expiry worker',$cmd$SELECT public.expire_pending_trades_atomic(1)$cmd$);
CALL pg_temp.version_write('veto settings',$cmd$UPDATE public.leagues SET trade_veto_mode='member_vote',trade_veto_threshold_percent=100 WHERE id=(SELECT league_id FROM version_fixture)$cmd$);
CALL pg_temp.version_write('offer for veto',$cmd$UPDATE version_fixture SET trade_id=pg_temp.version_trade_offer()$cmd$);
CALL pg_temp.version_write('accept for veto',$cmd$SELECT public.accept_trade_atomic(trade_id,member_ids[2]) FROM version_fixture$cmd$);
CALL pg_temp.version_write('veto vote',$cmd$SELECT public.veto_trade_atomic(trade_id,member_ids[3]) FROM version_fixture$cmd$);
CALL pg_temp.version_write('offer for completion failure',$cmd$UPDATE version_fixture SET trade_id=pg_temp.version_trade_offer()$cmd$);
CALL pg_temp.version_write('accept for completion failure',$cmd$SELECT public.accept_trade_atomic(trade_id,member_ids[2]) FROM version_fixture$cmd$);
CALL pg_temp.version_write('ready completion failure',$cmd$UPDATE public.trades SET veto_window_expires_at=now()-interval '1 minute' WHERE id=(SELECT trade_id FROM version_fixture)$cmd$);
CALL pg_temp.version_write('expire completion failure',$cmd$SELECT public.expire_trade_completion_failure_atomic(trade_id,'Version fixture failure') FROM version_fixture$cmd$);
SELECT set_config('request.jwt.claim.sub',(SELECT user_ids[1]::text FROM version_fixture),false);
CALL pg_temp.version_write('announcement',$cmd$SELECT public.notif_publish_announcement_atomic(league_id,'Version announcement',gen_random_uuid()) FROM version_fixture$cmd$);
CALL pg_temp.version_write('player watch',$cmd$SELECT public.notif_set_player_watch_atomic(league_id,players[8],true) FROM version_fixture$cmd$);
CALL pg_temp.version_write('claim for processing',$cmd$UPDATE version_fixture SET claim_id=public.create_waiver_claim_atomic(league_id,member_ids[1],players[6],NULL,user_ids[1],0)$cmd$);
CALL pg_temp.version_write('second claim for processing',$cmd$UPDATE version_fixture SET claim_id=public.create_waiver_claim_atomic(league_id,member_ids[1],players[7],NULL,user_ids[1],0)$cmd$);
CALL pg_temp.version_write('reorder pending claim',$cmd$SELECT public.reorder_waiver_claim_atomic(claim_id,member_ids[1],user_ids[1],'up') FROM version_fixture$cmd$);
CALL pg_temp.version_write('ready waiver processing',$cmd$UPDATE public.waiver_claims SET process_date=current_date-1 WHERE league_id=(SELECT league_id FROM version_fixture) AND status='pending'$cmd$);
SET request.jwt.claim.sub='';
CALL pg_temp.version_write('next waiver worker',$cmd$SELECT public.process_next_waiver_claim_atomic(current_date)$cmd$);
CALL pg_temp.version_write('due waiver worker',$cmd$SELECT public.process_due_waiver_claims_atomic(current_date,1)$cmd$);
SELECT set_config('request.jwt.claim.sub',(SELECT user_ids[1]::text FROM version_fixture),false);
